def dividiere(a, b):
    if b == 0:
        raise ValueError("Division durch null ist nicht erlaubt.")
    return a / b

def maximum(werte):
    if not werte:
        return None
    return max(werte)

def durchschnitt(zahlen):
    if not zahlen:
        return None
    return sum(zahlen) / len(zahlen)

def ist_palindrom(wort):
    normalisiert = wort.casefold()
    return normalisiert == normalisiert[::-1]

def fakultaet(n):
    if n < 0:
        raise ValueError("n muss nichtnegativ sein.")
    ergebnis = 1
    for zahl in range(2, n + 1):
        ergebnis *= zahl
    return ergebnis

def entferne_duplikate(werte):
    ergebnis = []
    gesehen = set()
    for wert in werte:
        if wert not in gesehen:
            gesehen.add(wert)
            ergebnis.append(wert)
    return ergebnis
